// Simulation replacements for the Altera PLLs.
// Clocks are generated by the C++ harness, which writes the public regs below.

module pll
(
	input  wire        refclk,
	input  wire        rst,
	output wire        outclk_0,          // clk48  (OPL3)
	output wire        outclk_1,          // clk64  (SDRAM, CLK_VIDEO)
	output wire        outclk_2,          // clk_sys
	output wire        locked,
	input  wire [63:0] reconfig_to_pll,
	output wire [63:0] reconfig_from_pll
);

reg clk48  /*verilator public_flat_rw*/ = 0;
reg clk64  /*verilator public_flat_rw*/ = 0;
reg clksys /*verilator public_flat_rw*/ = 0;
reg lock   /*verilator public_flat_rw*/ = 0;

assign outclk_0 = clk48;
assign outclk_1 = clk64;
assign outclk_2 = clksys;
assign locked   = lock;
assign reconfig_from_pll = 64'd0;

endmodule

// PAL/NTSC reconfiguration: accept writes, never stall. The harness keeps the
// PAL frequencies (NTSC timing is not modelled).
module pll_cfg
(
	input  wire        mgmt_clk,
	input  wire        mgmt_reset,
	output wire        mgmt_waitrequest,
	input  wire        mgmt_read,
	output wire [31:0] mgmt_readdata,
	input  wire        mgmt_write,
	input  wire  [5:0] mgmt_address,
	input  wire [31:0] mgmt_writedata,
	output wire [63:0] reconfig_to_pll,
	input  wire [63:0] reconfig_from_pll
);

assign mgmt_waitrequest = 1'b0;
assign mgmt_readdata    = 32'd0;
assign reconfig_to_pll  = 64'd0;

endmodule

// Cassette ADC input: no signal.
module ltc2308_tape #(parameter HIST_LOW = 16, HIST_HIGH = 64, ADC_RATE = 48000, CLK_RATE = 50000000, NUM_CH = 1)
(
	input         reset,
	input         clk,
	inout  [3:0]  ADC_BUS,
	output reg    dout,
	output        active,
	output        adc_sync,
	output [(NUM_CH*12)-1:0] adc_data
);

initial dout = 1'b0;
assign active   = 1'b0;
assign adc_sync = 1'b0;
assign adc_data = '0;

endmodule
